head.script:
//
(function(){
  var XHTML_NS="http://www.w3.org/1999/xhtml";
  var root=document.querySelector("foreignObject").firstElementChild;
  var originalCreateElement=document.createElement.bind(document);
  var originalCreateElementNS=document.createElementNS.bind(document);
  Object.defineProperty(document,"head",{get:function(){return root.querySelector("head");},configurable:true});
  Object.defineProperty(document,"body",{get:function(){return root.querySelector("body");},configurable:true});
  Object.defineProperty(document,"documentElement",{get:function(){return root;},configurable:true});
  document.createElement=function(tagName,options){
    if(typeof tagName==="string")return originalCreateElementNS(XHTML_NS,tagName,options);
    return originalCreateElement(tagName,options);
  };
  document.createElementNS=function(namespaceURI,qualifiedName,options){
    if(namespaceURI==null||namespaceURI===XHTML_NS)return originalCreateElementNS(XHTML_NS,qualifiedName,options);
    return originalCreateElementNS(namespaceURI,qualifiedName,options);
  };
})();
//

//
(function(){
  /* Opium infrastructure only (TongSherbet loader + local sw.js) — not Opium UI */
  try {
    var dir = location.pathname.replace(/[^/]+$/,"");
    window.swPath = location.origin + dir + "sw.js";
    if (location.pathname.indexOf("/gh/") < 0) {
      window.swPath = location.origin + "/gh/Mo9nikeypurple/skool/sw.js";
    }
  } catch(e) {
    window.swPath = location.origin + "/gh/Mo9nikeypurple/skool/sw.js";
  }
  console.log("[proxy-svg] swPath", window.swPath, "href", location.href);

  var mirrors = [
    "https://cdn.jsdelivr.net/gh/TongSherbet/storage/",
    "https://fastly.jsdelivr.net/gh/TongSherbet/storage/",
    "https://gcore.jsdelivr.net/gh/TongSherbet/storage/",
    "https://quantil.jsdelivr.net/gh/TongSherbet/storage/",
    "https://jsdelivr.b-cdn.net/gh/TongSherbet/storage/"
  ];
  // Prefer same jsDelivr host as this page for assets when possible
  try {
    if (/jsdelivr\.net$/i.test(location.hostname)) {
      mirrors.unshift("https://" + location.hostname + "/gh/TongSherbet/storage/");
    }
  } catch(e) {}

  var hour = Math.floor(Date.now()/3600000);
  var target = "";
  try {
    var q = new URL(location.href).searchParams;
    target = q.get("url") || q.get("u") || "";
  } catch(e) {}
  if (!target && location.hash && location.hash.length > 1) {
    target = decodeURIComponent(location.hash.slice(1));
  }
  window.__PROXY_TARGET = target;

  function setMsg(t) {
    var m = document.getElementById("msg");
    if (m) m.textContent = t;
    console.log("[proxy-svg]", t);
  }

  (async function(){
    setMsg("Loading Opium proxy stack…");
    var loaded = false;
    for (var i = 0; i < mirrors.length; i++) {
      try {
        var res = await fetch(mirrors[i] + "loader.js?" + hour + "&raw", {
          cache: "no-store",
          signal: AbortSignal.timeout(8000)
        });
        if (!res.ok) continue;
        var txt = await res.text();
        if (!txt || txt.length < 400) continue;
        if (!/serviceWorker|function/.test(txt)) continue;
        window.assetsBase = mirrors[i];
        var s = document.createElement("script");
        s.textContent = txt;
        document.head.appendChild(s);
        loaded = true;
        setMsg("Proxy stack loaded. Target: " + (target || "(none)"));
        break;
      } catch (e) {}
    }
    if (!loaded) {
      setMsg("Failed to load TongSherbet loader.js — check network");
      return;
    }
    // If loader exposes navigation later, try common hooks
    if (target) {
      var tries = 0;
      var timer = setInterval(function(){
        tries++;
        try {
          if (typeof window.openUrl === "function") { window.openUrl(target); clearInterval(timer); return; }
          if (typeof window.navigate === "function") { window.navigate(target); clearInterval(timer); return; }
          if (window.scramjet && typeof window.scramjet.navigate === "function") {
            window.scramjet.navigate(target); clearInterval(timer); return;
          }
          // Hash route some builds use
          if (tries === 3 && !location.hash) {
            location.hash = encodeURIComponent(target);
          }
        } catch (e) {}
        if (tries > 40) clearInterval(timer);
      }, 500);
    }
  })();
})();
//
